mapper.select:
SELECT id AS room_id, name, location_note, capacity::integer AS capacity, gender_option_id,
       sort_order, version
FROM rooms
WHERE space_id = #{spaceId} AND event_id = #{eventId}
AND id = #{roomId}
ORDER BY sort_order, id

mapper.update:
UPDATE rooms
SET name = #{name}, location_note = #{locationNote}, capacity = #{capacity},
    gender_option_id = #{genderOptionId}, version = version + 1, updated_at = #{at}
WHERE space_id = #{spaceId} AND event_id = #{eventId} AND id = #{roomId}

mapper.select:
SELECT p.id AS participant_id, p.name, (app.id IS NOT NULL) AS submitted, app.id AS application_id, nullif(btrim(coh.value ->> 'text'), '') AS cohort, gen.value ->> 'optionId' AS gender_option_id, (SELECT o ->> 'label' FROM jsonb_array_elements(gen.config -> 'options') o WHERE o ->> 'optionId' = gen.value ->> 'optionId' LIMIT 1) AS gender_label, coalesce(( SELECT NOT coalesce((o ->> 'hidden')::boolean, false) FROM jsonb_array_elements(gen.config -> 'options') o WHERE o ->> 'optionId' = gen.value ->> 'optionId' LIMIT 1), false) AS gender_shown, (att.config IS NOT NULL) AS attendance_asked, att.value ->> 'optionId' AS attendance_option_id, mea.value::text AS meals_answer, arr.value::text AS arrival_answer, dep.value::text AS departure_answer, (lod.config IS NOT NULL) AS lodging_asked, lod.value::text AS lodging_answer, nol.value::text AS no_lodging_answer, ra.room_id, ra.basis::text AS basis, ra.basis_at FROM participants p LEFT JOIN LATERAL () app ON true LEFT JOIN LATERAL (
) coh ON true LEFT JOIN LATERAL (
) gen ON true LEFT JOIN LATERAL (
) att ON true LEFT JOIN LATERAL (
) mea ON true LEFT JOIN LATERAL (
) arr ON true LEFT JOIN LATERAL (
) dep ON true LEFT JOIN LATERAL (
) lod ON true LEFT JOIN LATERAL (
) nol ON true LEFT JOIN room_assignments ra ON ra.space_id = p.space_id AND ra.event_id = p.event_id AND ra.participant_id = p.id AND ra.night = 0 WHERE p.space_id = #{spaceId} AND p.event_id = #{eventId}
AND p.id IN
#{id}
ORDER BY p.name COLLATE "C", p.id

SELECT p.id AS participant_id, p.name, nullif(btrim(coh.value ->> 'text'), '') AS cohort, (SELECT o ->> 'label' FROM jsonb_array_elements(gen.config -> 'options') o WHERE o ->> 'optionId' = gen.value ->> 'optionId' AND coalesce((o ->> 'hidden')::boolean, false) = false LIMIT 1) AS gender_label FROM participants p JOIN LATERAL () app ON true LEFT JOIN LATERAL (
) coh ON true LEFT JOIN LATERAL (
) gen ON true WHERE p.space_id = #{spaceId} AND p.event_id = #{eventId} AND p.id IN
#{id}
ORDER BY p.name COLLATE "C", p.id

mapper.update:
UPDATE room_assignments
SET basis = CAST(#{basis} AS jsonb), basis_at = #{at}, updated_by = #{actorUserId},
    updated_at = #{at}
WHERE space_id = #{spaceId} AND event_id = #{eventId} AND participant_id = #{participantId}
  AND night = 0

mapper.delete:
DELETE FROM room_assignments
WHERE space_id = #{spaceId} AND event_id = #{eventId} AND participant_id = #{participantId}
  AND night = 0
